49:             next = row[i + 1];
50:             let t1 = op(prev, next);
51:             let t2 = op(nextrow[i], prevrow[i]);
52:             dst[i] = op(curr, op(t1, t2));
53:         }
54:         let t1 = op(curr, next);
55:         let t2 = op(nextrow[width - 1], prevrow[width - 1]);
56:         dst[width - 1] = op(curr, op(t1, t2));
57:     }
58: }
