383: /// Repeats mediancut with different histogram weights to find palette with minimum error.
384: ///
385: ///  `feedback_loop_trials` controls how long the search will take. < 0 skips the iteration.
386: #[allow(clippy::or_fun_call)]
387: pub(crate) fn find_best_palette(attr: &Attributes, target_mse: f64, target_mse_is_zero: bool, max_mse: Option<f64>, mut hist: HistogramInternal) -> Result<(PalF, Option<f64>), Error> {
388:     // hist.items includes fixed colors already
389:     let few_input_colors = hist.items.len() <= attr.max_colors as usize;
390:     // actual target_mse passed to this method has extra diff from posterization
391:     if few_input_colors && target_mse_is_zero {
392:         return Ok(palette_from_histogram(&hist, attr.max_colors));
393:     }
394: 
395:     let mut max_colors = attr.max_colors;
396:     let total_trials = attr.feedback_loop_trials(hist.items.len()) as i16;
397:     let mut trials_left = total_trials;
398:     let mut best_palette = None;
399:     let mut target_mse_overshoot = if total_trials > 0 { 1.05 } else { 1. };
400:     let mut fails_in_a_row = 0;
401:     let mut palette_error = None;
402:     let mut palette = loop {
403:         let max_mse_per_color = target_mse.max(palette_error.unwrap_or(quality_to_mse(1))).max(quality_to_mse(51)) * 1.2;
404:         let mut new_palette = mediancut(&mut hist, max_colors, target_mse * target_mse_overshoot, max_mse_per_color)?
405:             .with_fixed_colors(attr.max_colors, &hist.fixed_colors);
406: 
407:         let stage_done = (f32::from(trials_left.max(0)) / f32::from(total_trials + 1)).mul_add(-(f32::from(trials_left.max(0)) / f32::from(total_trials + 1)), 1.);
408:         let overall_done = stage_done.mul_add(f32::from(attr.progress_stage2), f32::from(attr.progress_stage1));
409:         attr.verbose_print(format!("  selecting colors...{}%", (100. * stage_done) as u8));
410: 
411:         if trials_left <= 0 { break Some(new_palette); }
412: 
